INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das AIDA-Prinzip nur für Werbung relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Verkauf und Kommunikation"}, {"text": "Ja", "correct": false, "because": "Breiter anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phase des AIDA-Prinzips kommt zuerst?', 3, '[{"text": "Attention", "correct": true, "because": "Erregt Aufmerksamkeit"}, {"text": "Interest", "correct": false, "because": "Folgt Attention"}, {"text": "Desire", "correct": false, "because": "Spätere Phase"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen gehören zum AIDA-Prinzip?', 5, '[{"text": "Attention", "correct": true, "because": "Startet den Prozess"}, {"text": "Interest", "correct": true, "because": "Weckt Neugier"}, {"text": "Delivery", "correct": false, "because": "Kein Teil des Modells"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Desire weckt Kaufwunsch. b) Action ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Action ist Ziel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Anwendung des AIDA-Prinzips?', 4, '[{"text": "Zielgruppenanalyse", "correct": false, "because": "Wichtig für Wirkung"}, {"text": "Kundenreaktion", "correct": false, "because": "Misst Erfolg"}, {"text": "Firmengröße", "correct": true, "because": "Irrelevant für Modell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Interest vor Desire kommt?', 2, '[{"text": "Ja", "correct": true, "because": "Logische Reihenfolge"}, {"text": "Nein", "correct": false, "because": "Falsche Abfolge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phase zielt auf den Kauf ab?', 3, '[{"text": "Action", "correct": true, "because": "Fordert Handlung"}, {"text": "Desire", "correct": false, "because": "Weckt nur Wunsch"}, {"text": "Attention", "correct": false, "because": "Erste Stufe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Desire-Phase?', 5, '[{"text": "Emotionaler Anreiz", "correct": true, "because": "Steigert Wunsch"}, {"text": "Klarer Nutzen", "correct": true, "because": "Überzeugt Kunden"}, {"text": "Lieferdetails", "correct": false, "because": "Später relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) AIDA ist ein Verkaufsmodell. b) Es funktioniert nur online. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch offline nutzbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei AIDA unwichtig?', 4, '[{"text": "Kundenansprache", "correct": false, "because": "Kern der Phasen"}, {"text": "Call-to-Action", "correct": false, "because": "Wichtig für Action"}, {"text": "Produktionskosten", "correct": true, "because": "Kein Marketingfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Attention immer visuell?', 2, '[{"text": "Nein", "correct": true, "because": "Auch akustisch möglich"}, {"text": "Ja", "correct": false, "because": "Nicht eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das AIDA-Prinzip?', 4, '[{"text": "Strukturierter Ansatz", "correct": true, "because": "Klarer Prozess"}, {"text": "Kundenfokussierung", "correct": true, "because": "Zielt auf Bedürfnisse"}, {"text": "Kostensenkung", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass AIDA veraltet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Immer noch effektiv"}, {"text": "Ja", "correct": false, "because": "Nicht überholt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der AIDA-Strategie?', 3, '[{"text": "Kundenaufmerksamkeit", "correct": true, "because": "Startet den Prozess"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Wirkung wichtiger"}, {"text": "Produktpreis", "correct": false, "because": "Später relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Interest weckt Neugier. b) Desire ist die erste Phase.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Desire folgt später"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat das AIDA-Prinzip?', 5, '[{"text": "Vereinfachung", "correct": true, "because": "Ignoriert komplexe Prozesse"}, {"text": "Fehlende Nachhaltigkeit", "correct": true, "because": "Fokus auf kurzfristige Action"}, {"text": "Hohe Flexibilität", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist in der Action-Phase unwichtig?', 3, '[{"text": "Call-to-Action", "correct": false, "because": "Kern der Phase"}, {"text": "Kaufanreiz", "correct": false, "because": "Motiviert Handlung"}, {"text": "Produktgewicht", "correct": true, "because": "Kein Marketingfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann AIDA auch für Dienstleistungen genutzt werden?', 3, '[{"text": "Ja", "correct": true, "because": "Universell einsetzbar"}, {"text": "Nein", "correct": false, "because": "Nicht eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Attention laut sein muss?', 2, '[{"text": "Nein", "correct": true, "because": "Subtil möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel gestaltbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für die Interest-Phase?', 4, '[{"text": "Relevante Informationen", "correct": true, "because": "Hält Aufmerksamkeit"}, {"text": "Hohe Rabatte", "correct": false, "because": "Später in Desire"}, {"text": "Lieferzeiten", "correct": false, "because": "Nach Action"}]');
